INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3269, 'បន្ទាត់ \(a \parallel b\) ត្រូវកាត់ដោយខ្នាត់ \(t\)។ មុំក្នុងរួមខាងមួយគូមាន \(3x + 10\) និង \(2x + 20\) (ដឺក្រេ)។ រក \(x\) និងមុំទាំងពីរ។', NULL, '[]', 0, NULL, 5, 'writing', 'មុំក្នុងរួមខាងបូកបាន \(180^\circ\) ៖ \((3x+10)+(2x+20) = 180\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3270, 'ផ្លូវរថភ្លើងពីរស្របគ្នា ត្រូវកាត់ដោយថ្នល់ត្រង់មួយ។ នៅចំណុចកាត់ទី ១ មុំស្រួចមួយ \(70^\circ\)។ ក. គណនាមុំផ្សេងទៀតនៅចំណុចកាត់ទី ១។ ខ. គណនាមុំទាំងបួននៅចំណុចកាត់ទី ២។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. មុំស្រួច \(70^\circ\) ពីរ (ទល់កំពូល) និងមុំទាល \(110^\circ\) ពីរ (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3271, 'ដំបូលផ្ទះរាងត្រីកោណមានមុំមូលដ្ឋាន \(50^\circ\) និង \(60^\circ\)។ ក. រកមុំនៅកំពូល។ ខ. គេគូសបន្ទាត់ស្របនឹងបាតកាត់តាមកំពូល ផ្គុំមុំឆ្លាស់ក្នុងជាមួយជ្រុងទាំងពីរ។ រកមុំទាំងពីរនោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(180 - 50 - 60 = 70^\circ\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3272, 'តារាងកញ្ចក់ទ្វារមានបន្ទាត់ឈរ \(p \parallel q\) ហើយខ្នាត់ទ្រេត \(m\) ផ្គុំមុំស្រួច \(55^\circ\) ជាមួយ \(p\)។ ក. រកមុំឆ្លាស់ក្នុងជាមួយ \(q\)។ ខ. រកមុំក្នុងរួមខាង។ គ. ផលបូកមុំក្នុងរួមខាងស្មើប៉ុន្មាន?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. មុំឆ្លាស់ក្នុង \(55^\circ\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3273, 'ផ្លូវ \(a\) និង \(b\) ស្របគ្នា ហើយផ្លូវ \(m\) កែងនឹង \(a\)។ ក. \(m\) និង \(b\) មានទំនាក់ទំនងយ៉ាងណា? ខ. ផ្លូវ \(c\) ស្របនឹង \(m\) តើ \(c\) និង \(a\) ទំនាក់ទំនងយ៉ាងណា?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(m \perp a\) និង \(a \parallel b\) ដូច្នេះ \(m \perp b\) (2 ពិន្ទុ)
